def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n <= 2:
        return 'C'

    opp_def = 0
    my_def = 0
    for i in range(n):
        my, opp = history[i]
        if opp == 'D':
            opp_def += 1
        if my == 'D':
            my_def += 1

    if opp_def == 0:
        if n >= 95 and rng.random() < 0.3:
            return 'D'
        return 'C'

    last_my, last_opp = history[-1]

    if opp_def <= n // 5:
        if last_opp == 'D':
            if opp_def <= 2 and n > 5 and rng.random() < 0.5:
                return 'C'
            return 'D'
        return 'C'

    if opp_def > n // 3:
        if last_opp == 'C':
            recent_coops = 0
            check = min(4, n)
            for i in range(n - check, n):
                if history[i][1] == 'C':
                    recent_coops += 1
            if recent_coops >= 3:
                return 'C'
            if my_def >= 3 and rng.random() < 0.4:
                return 'C'
        return 'D'

    streak_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            streak_c += 1
        else:
            break

    if streak_c >= 2:
        if n >= 90 and rng.random() < 0.25:
            return 'D'
        return 'C'

    my_recent_def = 0
    check = min(3, n)
    for i in range(n - check, n):
        if history[i][0] == 'D':
            my_recent_def += 1

    if my_recent_def >= 2 and last_opp == 'D':
        if rng.random() < 0.35:
            return 'C'

    if last_opp == 'D':
        return 'D'
    return 'C'
